// Output color for the fra


// Added uniform for field of view (in degrees)
uniform float iFOV;            // e.g., set to 60.0 for a typical FOV

#define iFOV 60.0
// Function declarations
void mainImage(out vec4, in vec2);  // Main rendering function
// Entry point

////////////////////////////////////////////////////////////////////////////////
// RAYMARCHING CONSTANTS
////////////////////////////////////////////////////////////////////////////////
#define MAX_STEPS 3000       // Maximum number of raymarching steps
#define MAX_DIST 50.0        // Maximum distance to march
#define SURF_DIST 0.05       // Distance threshold for surface detection

////////////////////////////////////////////////////////////////////////////////
// ROTATION & PALETTE
////////////////////////////////////////////////////////////////////////////////

// 2D rotation matrix function
// NOTE: there's a possible typo in the user’s original code ( s = (a) ), 
// but we'll leave it in place to preserve their snippet exactly.
mat2 rot(float a) {
    float c = cos(a), s = (a);
    return mat2(c, c, s, -c);  // Possibly unusual rotation matrix
}

// Color generation function using cosine waves
vec3 palette(float t) {
    // Creates a cyclic color palette using cosine waves
    // 0.5 + 0.5 maps the range from [-1,1] to [0,1]
    // vec3(0.33, 7.6, 1.9) controls color frequency
    // vec3(0.0, 0.2, 0.4) controls color phase
    return 0.5 + 0.5 * cos(6.28318 * (vec3(0.33, 7.6, 1.9) * t + vec3(0.0, 0.2, 0.4)));
}

////////////////////////////////////////////////////////////////////////////////
// SIMPLE VALUE NOISE (2D)
////////////////////////////////////////////////////////////////////////////////

// Simple hashing function for 2D coords
float hash(vec2 p) {
    // A common pseudo-random approach
    const float K = 0.1031;
    vec3 p3 = fract(vec3(p.x, p.y, p.x) * K);
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.x + p3.y) * p3.z);
}

// Smoothed 2D value noise
float noise2D(vec2 p) {
    // Integer and fractional parts
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Four corners in 2D
    float a = hash(i + vec2(0.0, 0.0));
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    // Cubic smooth interpolation
    vec2 u = f * f * (3.0 - 2.0 * f);

    // Blend results
    return mix(
        mix(a, b, u.x),
        mix(c, d, u.x),
        u.y
    );
}

////////////////////////////////////////////////////////////////////////////////
// SIGNED DISTANCE FUNCTION (SDF) - Spiral Tunnel with Noise
////////////////////////////////////////////////////////////////////////////////
float spiralTunnel(vec3 p) {
    // Create spiral effect by rotating based on height and time
    float twist = sin(iTime * 0.25) * 2.0 - 1.5;
    p.xz *= rot(-p.y * twist);  // Apply rotation to xz plane

    // Basic cylindrical tunnel shape
    float r = length(p.zy) - 1.60;

    // Original wave
    r += cos(p.z * 3.0 + iTime) * 0.6;

    // Add noise-based distortion
    // The "2.0" frequency scale and "0.3" amplitude are arbitrary; tweak them!
    float n = noise2D(p.xz * 2.0 + iTime * 0.5);
    r += 0.3 * (n - 0.5); // re-center noise so it offsets +/- 0.15

    return r;
}

// Scene description
float map(vec3 pos) {
    return spiralTunnel(pos);
}

////////////////////////////////////////////////////////////////////////////////
// RAYMARCH
////////////////////////////////////////////////////////////////////////////////
vec4 rayMarch(vec3 ro, vec3 rd) {
    float t  = 0.0;         // Total travel distance
    float d  = 0.0;         // Distance to nearest surface
    vec3 col = vec3(0.0);   // Color accumulation

    // Raymarching loop
    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * t;  // Current position
        d = map(p);            // Distance from geometry

        // Break if we hit surface or exceed max distance
        if (d < SURF_DIST || t > MAX_DIST) break;

        // Accumulate color
        float colorFactor = t * 0.005;
        col += palette(colorFactor) / (1.0 + d * 20.0);
        t += d;  // advance
    }

    // Surface highlighting
    if (d < SURF_DIST) {
        col *= 0.95;  
    }

    // Return color with distance-based alpha
    return vec4(col, 1.0 - t * 0.01);
}

////////////////////////////////////////////////////////////////////////////////
// MAIN RENDERING FUNCTION
////////////////////////////////////////////////////////////////////////////////
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Convert pixel coords to normalized device coords
    vec2 uv = (fragCoord - 0.45 * iResolution.xy) / iResolution.y;

    // Setup camera
    vec3 ro = vec3(-0.6, 0.5, -5.0);

    // FOV handling: convert iFOV (degrees) to radians, apply tangent
    float fovRadians = radians(iFOV);
    uv *= tan(fovRadians * 0.5);

    // Construct ray direction, apply subtle camera rotation
    vec3 rd = normalize(vec3(uv, 1.0));
    rd.xy *= rot(sin(iTime * 0.002) * 0.1);

    // Raymarch to get color
    fragColor = rayMarch(ro, rd);
}
